import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter is an arbitrary caller address 'caller'
    function testFuzz_property(address caller) public {
        // keep caller varied but not the zero address to ensure meaningful caller
        vm.assume(caller != address(0));

        // The reference implementation stores the owner as the deployer (the address that ran __Ownable_init).
        // In setUp() we deployed C via this contract, so owner() should equal address(this) in the reference.
        // We exercise caller as an external EOA calling owner(). We use vm.prank to set tx.origin/caller context.

        // Call owner() as if 'caller' is the originator
        vm.prank(caller);
        address reportedOwner;
        bool ok;
        // owner() is a view, but we still call under vm.prank to set msg.sender/tx.origin for mutant behavior
        try c.owner() returns (address o) {
