            ok = true;
        } catch {
            // should not revert
            ok = false;
        }

        // Single assertion: the correct contract always reports the stored owner (the deployer of the contract, this test contract)
        // Therefore owner() must equal address(this) and the call must not revert. The mutant that returns tx.origin will
