pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an address that will act as an external caller (a proxy contract)
    function testFuzz_property(address proxyCaller) public {
        // keep proxyCaller non-zero to be meaningful; allow wide domain otherwise
        vm.assume(proxyCaller != address(0));

        // Deploy a minimal proxy contract that will call c.owner() on behalf of an EOA
        Caller cproxy = new Caller();

        // Ensure the proxy's address equals the fuzzed one by using CREATE2 is not allowed here,
        // so instead we treat `proxyCaller` as the EOA that will be tx.origin while the proxy calls c.owner().
        // We need tx.origin != deployer to detect the mutant, so require proxyCaller not equal to deployer (address(this)).
        vm.assume(proxyCaller != address(this));

        // Make proxy contract call c.owner() with tx.origin = proxyCaller by using vm.prank to set origin
        // vm.prank sets msg.sender and tx.origin for the next call when used with two-arg variant.
        // Forge's vm.prank(address) sets both msg.sender and tx.origin; we want tx.origin = proxyCaller and
        // the contract cproxy to be msg.sender. To achieve that, we use vm.prank(proxyCaller, address(cproxy))
        // so that tx.origin == proxyCaller and msg.sender == address(cproxy) in the call from cproxy.

        // First, have the proxy perform the external call to c.owner() and return the observed owner.
        // We will call Caller.callOwner which performs a staticcall to c.owner().

        vm.prank(proxyCaller, address(cproxy));
        address observed = cproxy.callOwner(address(c));

        // The correct contract stores owner as the deployer (address(this) when setUp run). So for all inputs,
        // the correct contract should return the deployer address regardless of tx.origin or intermediary caller.
        // We assert that the observed value equals address(this) (the deployer/owner of c).
        // This holds for the reference C for every admissible input; the mutant (returning tx.origin) will return
        // proxyCaller instead, causing the assertion to fail for those proxyCaller values different from deployer.

        assertTrue(observed == address(this));
    }
}

// Minimal helper that calls C.owner() and returns the result
contract Caller {
    function callOwner(address target) external returns (address) {
        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature("owner()"));
        if (!ok) return address(0);
        return abi.decode(ret, (address));
    }
}

