pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an address that will act as an external EOA originator.
    // We will have that EOA call a thin Proxy contract which will forward the call to c.owner().
    // General rule: reference's owner() always equals deployer (address(this) at setUp),
    // even when called via a proxy; mutant returns tx.origin, causing a mismatch when tx.origin != deployer.
    function testFuzz_property(address originator) public {
        // avoid zero address for clarity; keep wide domain
        vm.assume(originator != address(0));

        // Deploy a small forwarding proxy that will call c.owner() using msg.sender = proxy and tx.origin = originator
        Forwarder f = new Forwarder(c);

        // Fund the originator EOA so it can make the call (not strictly necessary for non-payable calls but harmless)
        vm.deal(originator, 1 ether);

        // Have the originator externally call the forwarder which in turn calls c.owner()
        vm.prank(originator);
        address returnedOwner = f.callOwner();

        // The correct contract always stores deployer (this test's setUp deployer) as owner.
        // The deployer was address(this) when new C() ran in setUp(), so read that stored owner directly from c.
        // Note: for the reference contract, c.owner() should equal the deployer regardless of caller/proxy.
        // We assert that the returnedOwner from the proxied call equals the stored owner getter when called directly.

        // Call the getter directly from this test contract (deployer) to obtain stored owner value.
        address directOwner = c.owner();

        // Exactly one assertion: the proxied call must return the same owner as the direct call.
        assertTrue(returnedOwner == directOwner);
    }
}

// Minimal forwarder that simply calls c.owner() and returns the address value.
contract Forwarder {
    C immutable target;
    constructor(C _target) {
        target = _target;
    }
    function callOwner() external returns (address) {
        // call the public owner() and return its result
        return target.owner();
    }
}

