    function testFuzz_property(address caller) public {
        // keep domain wide but exclude address(0) since an EOA zero is not useful
        vm.assume(caller != address(0));
        // Deploy a proxy that will call c.owner() and return the result
        ProxyCaller proxy = new ProxyCaller(address(c));

        // Give the fuzzed caller some ETH so it can initiate the call
        vm.deal(caller, 1 ether);

        // Make the fuzzed EOA be msg.sender/tx.origin for the external call
        vm.prank(caller);
        (bool ok, bytes memory ret) = address(proxy).call(abi.encodeWithSignature("callOwner()"));
        // Both reference and mutant complete the call; we only assert on the returned owner value
        // Decode returned owner if call succeeded
        address returnedOwner;
        if (ok && ret.length >= 32) {
            returnedOwner = abi.decode(ret, (address));
        } else {
            returnedOwner = address(0);
        }

        // The stored owner in the reference contract is the deployer (set in __Ownable_init called by initialize),
        // but since setUp deployed C with new C() and did not call initialize, Ownable's _owner was set to address(0)
