    C c;
    function setUp() public { c = new C(); }

    // fuzz the candidate newOwner; the property: for any newOwner != address(0) transferOwnership should succeed and owner()==newOwner
    function testFuzz_property(address newOwner) public {
        // keep wide: allow any address including zero; we will observe behavior
        // ensure caller is current owner (deployer), since transferOwnership is onlyOwner
        address deployer = address(this);
        // sanity: c.owner() initially is address(this) because constructor path calls __Ownable_init in initialize, but in our test C was deployed without initialize; however tests should use onlyOwner requirement — to ensure we are owner, we call transferOwnership from owner via direct call: first call _transferOwnership by invoking transferOwnership as owner. The contract as deployed sets _owner to address(0) unless __Ownable_init was run; to ensure caller is owner we emulate ownership by directly invoking transferOwnership only when owner()==address(this) OR if not, first set ownership by calling c.transferOwnership(address(this)) inside a try/catch — we will handle both cases.

        bool ok;
        // Attempt to ensure we are owner; if not owner, try calling transferOwnership as current owner by reading owner()
        address current = c.owner();
        if (current != address(this)) {
            // we are not owner. Try to have current owner transfer to us. Since we cannot call as current owner, and we must run transferOwnership as onlyOwner, the only viable path is: if current==address(0) then anybody can NOT call onlyOwner. To keep test valid across deployments, require that current==address(this) so we only exercise transferOwnership as rightful owner.
            // Constrain to inputs where we are owner to keep property meaningful
            vm.assume(current == address(this));
        }

        // Now call transferOwnership(newOwner) as owner (this)
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract requires newOwner != address(0) so for any newOwner != zero the call must succeed and owner()==newOwner.
        // We assert that if call succeeded then owner()==newOwner; this holds for the correct contract for all inputs, but the mutant will allow success when newOwner==address(0) and owner()==address(0), which violates the original rule that zero address cannot become owner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

