        c = new C();
        sGlp = new MockERC20();
        usdc = new MockERC20();
        rr = new MockRewardRouter();
        gm = new MockGlpManager();
        jv = new MockJuniorVault();
        vault = new MockVault();
        // initialize the contract c as this test contract (msg.sender = address(this)) to become owner
        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(rr)), IGlpManager(address(gm)), address(jv), address(this));
    }

    // Single fuzz test: fuzz newOwner address. The reference should revert when newOwner==address(0); mutant will not.
    function testFuzz_property(address newOwner) public {
        // no restrictive assumes — allow zero to be tested
        bool ok;
        // call transferOwnership as the owner (this contract)
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // The universal property: the reference MUST reject (revert) when newOwner == address(0).
        // So for every admissible input (we allow any address), if newOwner == address(0) then transferOwnership must revert -> ok == false.
        if (newOwner == address(0)) {
            assertTrue(!ok);
        } else {
            // For non-zero addresses, both reference and mutant succeed; to keep the assertion a single one per test, we assert that if newOwner != zero then ok == true.
            // This keeps the property universal: reference allows any non-zero newOwner and rejects zero.
            assertTrue(ok);
        }
    }
}

